import {lenses,validateBoard,newPlayState,logDecision,recoverPreviousState} from './board-model.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalog=await(await fetch('/private/catalog.json')).json();let priorPlay,priorPin,board,play,current,lens='Situation',view='cards',mode='plan';
$('#adventure').innerHTML=catalog.boards.map(b=>`<option value="${esc(b.id)}">${esc(b.title)}</option>`).join('');
function key(){return 'dmb-private-board-v1:'+board.id+':'+board.pin}
function save(status){if(status)play.savedAt=new Date().toISOString();try{localStorage.setItem(key(),JSON.stringify(play));if(status)status.textContent='Saved at '+new Date().toLocaleTimeString('en-US',{timeZone:'America/Denver'})+' · this browser'}catch{if(status)status.textContent='Not saved · copy your writing; browser storage unavailable'}}
async function load(id){const item=catalog.boards.find(b=>b.id===id);board=await(await fetch(item.url)).json();const errors=validateBoard(board);if(errors.length)throw Error(errors.join('; '));try{play=JSON.parse(localStorage.getItem(key()))}catch{}play??=newPlayState();priorPlay=null;for(const pin of board.previousPins??[]){try{const saved=JSON.parse(localStorage.getItem('dmb-private-board-v1:'+board.id+':'+pin));if(saved){priorPlay=saved;priorPin=pin;break}}catch{}}current=play.current??board.startCard??board.cards[0].id;lens=play.lens??'Situation';mode=play.mode??'plan';view=play.view??'cards';$('#search').value='';$('#padText').value=play.notes;$('#adventure').value=id;history.replaceState(null,'','?adventure='+encodeURIComponent(id));render()}
function show(title,html){$('#inspectorTitle').textContent=title;$('#inspectorBody').innerHTML=html;$('#inspector').showModal()}
function readback(refs){const units=refs.map(id=>board.units.find(u=>u.id===id));show('Exact source readback',units.map(u=>`<section><h3>PDF page ${u.page+1} · lines ${u.lineStart}–${u.lineEnd}</h3><p>${esc(u.text)}</p><a href="${esc(board.pdfUrl)}#page=${u.page+1}" target="_blank">Open PDF page</a><details><summary>Evidence identity</summary><p>${esc(u.id)}<br>Stage B: ${esc(u.unitHash)}<br>Surface: ${esc(u.surfaceHash)}</p></details></section>`).join(''))}
function sourceText(text){return text.split(/(<table>[\s\S]*?<\/table>)/g).map(part=>part.startsWith('<table>')?'<div class="board-table">'+[...part.matchAll(/<tr>([\s\S]*?)<\/tr>/g)].map(row=>'<div class="table-row">'+[...row[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map(cell=>'<span>'+esc(cell[1].replace(/<[^>]+>/g,''))+'</span>').join('')+'</div>').join('')+'</div>':'<p>'+esc(part)+'</p>').join('')}
function itemHTML(item){return `<section class="source-item ${item.status}"><div class="source-status">${esc(({'source_supported':'Source text · OCR audit pending','proposed_connective':'Suggested','reviewed_inference':'Reviewed interpretation','unresolved':'Needs review'})[item.status])}${item.refs.length?`<button data-readback="${esc(item.refs.join(','))}">Source · ${item.refs.length} span${item.refs.length===1?'':'s'}</button>`:''}</div>${item.speaker?'<strong>'+esc(item.speaker)+'</strong>':''}${item.condition?'<p class="scene-condition">'+esc(item.condition)+'</p>':''}${sourceText(item.text)}</section>`}
function render(){play.current=current;play.lens=lens;play.mode=mode;play.view=view;save();const card=board.cards.find(c=>c.id===current);const filter=$('#search').value.toLowerCase();const grouped=Object.groupBy?Object.groupBy(board.cards.filter(c=>(c.title+' '+c.group).toLowerCase().includes(filter)),c=>c.group):board.cards.filter(c=>(c.title+' '+c.group).toLowerCase().includes(filter)).reduce((groups,c)=>{(groups[c.group]??=[]).push(c);return groups},{});$('#index').innerHTML=Object.entries(grouped).sort(([a],[b])=>(board.outlineOrder??[]).indexOf(a)-(board.outlineOrder??[]).indexOf(b)).map(([group,cards])=>`<details ${filter||cards.some(c=>c.id===current)?'open':''}><summary>${esc(group)} · ${cards.length}</summary>${cards.map(c=>`<button data-card="${esc(c.id)}" class="${c.id===current?'active':''} ${play.completed[c.id]?'scene-complete':''}">${play.completed[c.id]?'✓ ':''}<span class="scene-title">${esc(c.title)}</span></button>`).join('')}</details>`).join('');$('#context').innerHTML=`<button id="outline">Outline</button><h2>${esc(card.title)}</h2><label><input id="done" type="checkbox" ${play.completed[current]?'checked':''}> Complete</label><span class="badge">${mode==='plan'?'Prep':'Play'} · private development</span>${priorPlay?'<button id="recoverPrevious">Recover previous writing</button>':''}${mode==='plan'&&view==='cards'?'<button id="editLens">Edit this lens</button><button id="addLens">Write another lens</button>':''}`;
 if(view==='document')$('#content').innerHTML=board.pages.map(p=>`<section class="source-page"><h3>Source PDF page ${p.page+1}</h3><pre style="white-space:pre-wrap;font:inherit">${esc(p.text)}</pre><a href="${esc(board.pdfUrl)}#page=${p.page+1}" target="_blank">PDF readback</a></section>`).join('');
 else {const available=lenses.filter(l=>card.lenses[l]?.length||play.edits?.[current+':'+l]);if(!available.includes(lens))lens=available[0];$('#content').innerHTML=`<div class="block-tabs">${available.map(l=>`<button data-lens="${esc(l)}" class="${l===lens?'active':''}">${esc(l)}</button>`).join('')}</div>${card.location?`<p class="scene-location">${esc(card.location)}</p>`:''}<section class="focused-block">${play.edits?.[current+':'+lens]?itemHTML({text:play.edits[current+':'+lens],status:'proposed_connective',refs:card.lenses[lens].flatMap(i=>i.refs)}):card.lenses[lens].map(itemHTML).join('')}</section><div class="related">${board.entities.filter(e=>e.refs.some(ref=>card.lenses['GM only'].some(i=>i.refs.includes(ref)))).map(e=>`<button class="node" data-inspect-entity="${esc(e.id)}">${esc(e.name)}</button>`).join('')}</div><div class="related">${(card.links??[]).map(link=>`<button data-card="${esc(link.target)}">${esc(link.label==='Next source section'?'Next card':link.label==='Previous source section'?'Previous card':link.label)} →${link.status==='reviewed_inference'?'<small>'+esc(link.condition)+'</small>':''}</button>`).join('')}${(card.assetIds??[]).map(id=>`<button data-asset="${esc(id)}">Map / image</button>`).join('')}</div>${card.choices?.length?`<details class="choice"><summary>Choices <span class="choice-hint">Click to expand</span></summary><p>Optional directions · multiple actions allowed</p>${card.choices.map(c=>`<div class="board-choice"><label><input type="checkbox" data-choice="${esc(c.id)}" ${(play.selected[current]??[]).includes(c.id)?'checked':''}>${esc(c.label)}</label><div class="source-status">${esc(c.status.replaceAll('_',' '))}<button data-readback="${esc(c.refs.join(','))}">Source</button></div><details><summary>Conditions & possible consequences</summary><p>${esc(c.consequence)}</p></details></div>`).join('')}<label>Something else<textarea id="other" placeholder="What did they do instead?">${esc(play.other[current]??'')}</textarea></label><small id="otherStatus">${play.savedAt?'Saved · this browser':'Autosave on · this browser'}</small><button id="log">Log player decisions</button><p id="logStatus"></p></details>`:''}<details class="scene-notes board-note"><summary>Scene notes</summary><textarea id="sceneNote">${esc(play.sceneNotes[current]??'')}</textarea><small id="sceneSave">${play.savedAt?'Saved · this browser':'Autosave on · this browser'}</small></details><details><summary>Play log · ${play.decisions.filter(d=>d.card===current).length}</summary>${play.decisions.filter(d=>d.card===current).map(d=>`<p>${esc(d.at)} · ${esc(d.choices.map(id=>card.choices?.find(c=>c.id===id)?.label??id).join('; '))}<br>${esc(d.note)}</p>`).join('')}</details><details><summary>Source review & assembly</summary>${(card.reviewDetails??[]).map(i=>'<p>'+esc(i.lens+': '+i.text)+'</p>').join('')}<p>${esc(card.audit)}</p><p>${esc(board.reviewStatus)}</p><a href="${esc(board.manifestUrl)}" target="_blank">Private reference manifest</a></details>`}
 if($('#recoverPrevious'))$('#recoverPrevious').onclick=()=>{show('Recover previous writing',`<label>Previous dataset<select id="recoveryPin">${(board.previousPins??[]).filter(pin=>localStorage.getItem('dmb-private-board-v1:'+board.id+':'+pin)).map(pin=>'<option>'+esc(pin)+'</option>').join('')}</select></label><p>Copy its notes, decisions, completion marks and preparation edits into this revision. Current writing is archived in this browser before copying; the previous dataset stays untouched. Existing edits may describe the older source grouping; review them against current citations.</p><button id="copyPrevious">Copy previous session state</button>`);$('#copyPrevious').onclick=()=>{const archiveKey=key()+':before-recovery:'+new Date().toISOString();localStorage.setItem(archiveKey,JSON.stringify(play));const chosen=JSON.parse(localStorage.getItem('dmb-private-board-v1:'+board.id+':'+$('#recoveryPin').value));play=recoverPreviousState(chosen,board);current=play.current;lens=play.lens??'Situation';$('#padText').value=play.notes??'';save();priorPlay=null;$('#inspector').close();render()}};
 if($('#addLens'))$('#addLens').onclick=()=>{show('Write a lens',`<label>Lens<select id="newLens">${lenses.map(l=>'<option>'+esc(l)+'</option>').join('')}</select></label><textarea id="newLensText"></textarea><button id="saveNewLens">Save preparation</button>`);$('#saveNewLens').onclick=()=>{lens=$('#newLens').value;play.edits??={};play.edits[current+':'+lens]=$('#newLensText').value;save();$('#inspector').close();render()}};
 if($('#editLens'))$('#editLens').onclick=()=>{const editKey=current+':'+lens;show('Edit '+lens,`<p>Your preparation override · original source and citations remain available.</p><textarea id="lensEdit">${esc(play.edits?.[editKey]??card.lenses[lens].map(i=>i.text).join('\n\n'))}</textarea><button id="saveLens">Save preparation</button><button id="resetLens">Use source projection</button>`);$('#saveLens').onclick=()=>{play.edits??={};play.edits[editKey]=$('#lensEdit').value;save();$('#inspector').close();render()};$('#resetLens').onclick=()=>{if(play.edits)delete play.edits[editKey];save();$('#inspector').close();render()}};
 document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>{current=b.dataset.card;lens='Situation';render()});document.querySelectorAll('[data-lens]').forEach(b=>b.onclick=()=>{lens=b.dataset.lens;render()});document.querySelectorAll('[data-readback]').forEach(b=>b.onclick=()=>readback(b.dataset.readback.split(',').filter(Boolean)));document.querySelectorAll('[data-inspect-entity]').forEach(b=>b.onclick=()=>entity(b.dataset.inspectEntity));document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>asset(b.dataset.asset));document.querySelectorAll('[data-choice]').forEach(b=>b.onchange=()=>{const ids=new Set(play.selected[current]??[]);b.checked?ids.add(b.dataset.choice):ids.delete(b.dataset.choice);play.selected[current]=[...ids];save()});$('#outline').onclick=()=>$('.workspace').classList.toggle('outline-hidden');$('#done').onchange=e=>{play.completed[current]=e.target.checked;save();render()};if($('#sceneNote'))$('#sceneNote').oninput=e=>{play.sceneNotes[current]=e.target.value;save($('#sceneSave'))};if($('#other'))$('#other').oninput=e=>{play.other[current]=e.target.value;save($('#otherStatus'))};if($('#log'))$('#log').onclick=()=>{play=logDecision(play,current,play.selected[current]??[],play.other[current]??'',new Date().toISOString());save();render()};['plan','play','cards','documentView'].forEach(id=>$('#'+id).classList.toggle('active',id===mode||(id==='documentView'?view==='document':id===view)))}
function asset(id){const a=board.assets.find(a=>a.id===id);show(a.title,`<p>GM reference · player-safe review pending · source PDF page ${a.page+1}</p><img class="asset" src="${esc(a.url)}" alt="${esc(a.title)}"><p>Image SHA-256: ${esc(a.hash)}</p>`)}
$('#maps').onclick=()=>{show('Maps & images',board.assets.map(a=>`<section class="entity-row"><button data-map="${esc(a.id)}">${esc(a.title)}</button><p>GM reference · page ${a.page+1}</p></section>`).join(''));document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{$('#inspector').close();asset(b.dataset.map)})};
function entity(id){const e=board.entities.find(e=>e.id===id);const appearances=board.cards.filter(c=>c.lenses['GM only'].some(i=>i.refs.some(ref=>e.refs.includes(ref))));const connections=(board.relationships??[]).filter(r=>r.subject.toLowerCase().includes(e.name.toLowerCase())||r.object.toLowerCase().includes(e.name.toLowerCase()));show(e.name,`<p>${esc(e.role)}</p><p class="coverage-note">Source-local entity candidate · live Graph and encounter state not connected</p>${connections.length?'<h3>Connections</h3><ul>'+connections.map(r=>'<li>'+esc(r.subject+' · '+r.predicate.replaceAll('_',' ')+' · '+r.object)+' <button data-readback="'+esc(r.refs.join(','))+'">Evidence</button></li>').join('')+'</ul>':''}${(e.profile??[]).map(p=>'<section><h3>'+esc(p.title)+'</h3><p>'+esc(p.text)+'</p><small>'+esc(p.attribution)+'</small><button data-readback="'+esc(p.refs.join(','))+'">Evidence</button></section>').join('')}<details><summary>Coverage limits</summary><p>${esc(e.coverageReview??'Initial candidate selectors; full identity review pending')}</p></details><h3>Scenes & references</h3><div class="related">${appearances.map(c=>`<button data-entity-card="${esc(c.id)}">${esc(c.title)} →</button>`).join('')}</div><h3>Entity notes</h3><textarea id="entityNote">${esc(play.entityNotes[e.id]??'')}</textarea><small id="entitySave"></small><details><summary>Source appearances · ${e.refs.length}</summary>${e.refs.map(ref=>itemHTML({status:'source_supported',refs:[ref],text:board.units.find(u=>u.id===ref).text})).join('')}</details>`);document.querySelectorAll('[data-entity-card]').forEach(b=>b.onclick=()=>{$('#inspector').close();current=b.dataset.entityCard;lens='GM only';render()});document.querySelectorAll('[data-readback]').forEach(b=>b.onclick=()=>{$('#inspector').close();readback(b.dataset.readback.split(','))});$('#entityNote').oninput=ev=>{play.entityNotes[e.id]=ev.target.value;save($('#entitySave'))}}
$('#entities').onclick=()=>{show('People, places & threats',board.entities.map(e=>`<section class="entity-row"><button data-entity="${esc(e.id)}">${esc(e.name)}</button><p>${esc(e.role)}</p></section>`).join(''));document.querySelectorAll('[data-entity]').forEach(b=>b.onclick=()=>{$('#inspector').close();entity(b.dataset.entity)})};
$('#adventure').onchange=e=>{play=null;load(e.target.value)};$('#search').oninput=render;$('#plan').onclick=()=>{mode='plan';render()};$('#play').onclick=()=>{mode='play';render()};$('#cards').onclick=()=>{view='cards';render()};$('#documentView').onclick=()=>{view='document';render()};$('#notes').onclick=()=>{$('#pad').hidden=!$('#pad').hidden};$('#closePad').onclick=()=>$('#pad').hidden=true;$('#padText').oninput=e=>{play.notes=e.target.value;save($('#saveStatus'))};$('#backup').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({format:'dmb-private-board-play-v1',boardId:board.id,sourcePin:board.pin,savedAt:new Date().toISOString(),play},null,2)],{type:'application/json'}));a.download=board.id+'-play-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
try{await load(new URLSearchParams(location.search).get('adventure')??catalog.boards[0].id)}catch(error){$('#content').textContent='Private board could not load: '+error.message}
